pub fn run_visual_loop(
    game_dir: &Path,
    options: PlayOptions,
    raster_depth: TileGraphicsDepth,
) -> std::io::Result<()> {
    let state = PlayState::load_scene(game_dir, options)?;
    let atlas = load_tile_atlas(game_dir, raster_depth)?;
    let text_font = load_ibm_ch_font(game_dir)?;
    let rune_font = load_runes_ch_font(game_dir)?;
    let bootstrap = Bootstrap {
        game_dir: game_dir.to_path_buf(),
        state,
        atlas,
        text_font,
        rune_font,
    };

    let display = aspect_corrected_display_size(
        VISUAL_PLAY_FRAME_WIDTH,
        VISUAL_PLAY_FRAME_HEIGHT,
        DISPLAY_SCALE,
    );
    let (display_w, display_h) = (display.x, display.y);

    // Headless screenshot driver: when U5_BEVY_SCREENSHOT is set, the harness
    // waits a few frames (so the swapchain has a real image), takes a
    // screenshot via Bevy's `Screenshot` component, then exits. Lets us
    // verify end-to-end Bevy rendering without an interactive desktop.
    let screenshot_path: Option<PathBuf> = optional_env_path("U5_BEVY_SCREENSHOT");
    let screenshot_delay: u32 = screenshot_delay_from_env();
    // Optional pre-screenshot keystrokes (single chars), e.g.
    // `U5_BEVY_PRESS=dddss` to step east 3 then south 2 before the shot.
    let preset_keys: Vec<char> = preset_keys_from_env();
    let mut app = App::new();
    app.add_plugins(DefaultPlugins.set(WindowPlugin {
        primary_window: Some(Window {
            title: "Ultima V".into(),
            resolution: (display_w, display_h).into(),
            resizable: true,
            ..default()
        }),
        ..default()
    }))
    .insert_resource(ClearColor(Color::BLACK))
    .insert_resource(PendingBootstrap(Mutex::new(Some(bootstrap))))
    .insert_resource(ScreenshotConfig {
        path: screenshot_path,
        frame_delay: screenshot_delay,
        preset_keys,
    })
    .insert_resource(ScreenshotState::default())
    .add_systems(Startup, setup)
    .insert_resource(AnimationPump::default())
    .add_systems(
        Update,
        (
            drive_visual,
            animate_static_tiles,
            fit_display_to_window,
            play_speaker_effects,
            expire_speaker_voice,
            screenshot_system,
        )
            .chain(),
    );
    add_speaker_audio(&mut app);
    app.run();

    Ok(())
}

pub fn run_visual_intro_loop(
    game_dir: &Path,
    raster_depth: TileGraphicsDepth,
) -> std::io::Result<()> {
    let launch_result = Arc::new(Mutex::new(None));
    run_visual_intro_menu_app(game_dir.to_path_buf(), raster_depth, launch_result.clone());
    Ok(())
}

fn optional_env_path(name: &str) -> Option<PathBuf> {
    match std::env::var(name) {
        Ok(value) => Some(PathBuf::from(value)),
        Err(std::env::VarError::NotPresent) => None,
        Err(err) => panic!("{name} could not be read: {err}"),
    }
}

fn screenshot_delay_from_env() -> u32 {
    match std::env::var("U5_BEVY_SCREENSHOT_DELAY") {
        Ok(value) => value.parse().unwrap_or_else(|err| {
            panic!("U5_BEVY_SCREENSHOT_DELAY must be an unsigned frame count: {err}")
        }),
        Err(std::env::VarError::NotPresent) => 60,
        Err(err) => panic!("U5_BEVY_SCREENSHOT_DELAY could not be read: {err}"),
    }
}

fn preset_keys_from_env() -> Vec<char> {
    match std::env::var("U5_BEVY_PRESS") {
        Ok(value) => value.chars().collect(),
        Err(std::env::VarError::NotPresent) => Vec::new(),
        Err(err) => panic!("U5_BEVY_PRESS could not be read: {err}"),
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct VisualFrameReport {
    pub label: String,
    pub path: PathBuf,
    pub width: u32,
    pub height: u32,
    pub frame_kind: &'static str,
    pub byte_hash: u64,
    pub nonblack_pixels: usize,
}

pub fn run_visual_frame_suite(
    game_dir: &Path,
    raster_depth: TileGraphicsDepth,
    out_dir: &Path,
) -> io::Result<()> {
    let reports = visual_frame_suite(game_dir, raster_depth, out_dir)?;
    for report in &reports {
        println!(
            "visual-suite {}: {}x{} {} hash {:016x} nonblack {} -> {}",
            report.label,
            report.width,
            report.height,
            report.frame_kind,
            report.byte_hash,
            report.nonblack_pixels,
            report.path.display()
        );
    }
    println!(
        "Saved Bevy visual frame suite: {} PNG(s) plus manifest at {}.",
        reports.len(),
        out_dir.join("manifest.txt").display()
    );
    Ok(())
}

pub fn run_visual_route_suite(
    game_dir: &Path,
    raster_depth: TileGraphicsDepth,
    out_dir: &Path,
) -> io::Result<()> {
    let reports = visual_route_suite(game_dir, raster_depth, out_dir)?;
    for report in &reports {
        println!(
            "visual-route {}: {}x{} {} hash {:016x} nonblack {} -> {}",
            report.label,
            report.width,
            report.height,
            report.frame_kind,
            report.byte_hash,
            report.nonblack_pixels,
            report.path.display()
        );
    }
    println!(
        "Saved Bevy visual route suite: {} PNG(s) plus manifest at {}.",
        reports.len(),
        out_dir.join("manifest.txt").display()
    );
    Ok(())
}

pub fn visual_frame_suite(
    game_dir: &Path,
    raster_depth: TileGraphicsDepth,
    out_dir: &Path,
) -> io::Result<Vec<VisualFrameReport>> {
    u5_runtime::test_fixtures::assert_writable_game_dir(out_dir, "visual frame suite output");
    std::fs::create_dir_all(out_dir)?;
    let atlas = load_tile_atlas(game_dir, raster_depth)?;
    let font = load_ibm_ch_font(game_dir)?;
    let runes = load_runes_ch_font(game_dir)?;
    let ctx = PlayFrameContext {
        ibm: &font,
        runes: &runes,
        game_dir,
        cursor_frame: 0,
    };
    let mut reports = Vec::new();

    for case in visual_gameplay_frame_cases() {
        let mut state = PlayState::load_scene(game_dir, case.options)?;
        if case.synthetic_combat {
            seed_visual_suite_combat(&mut state, game_dir)?;
        }
        if let Some(configure) = case.configure {
            configure(&mut state);
        }
        if case.label == "endgame-status" {
            state.enter_endgame_from_game_dir(Some(game_dir))?;
        }
        if let Some(inputs) = case.inputs {
            for (key, suffix) in inputs {
                handle_play_key_input(&mut state, *key, suffix, game_dir)?;
            }
        }
        reports.push(write_visual_play_report(
            out_dir,
            case.label,
            case.frame_kind,
            &mut state,
            &atlas,
            ctx,
        )?);
    }
    push_visual_combat_gallery_reports(game_dir, out_dir, &atlas, ctx, &mut reports)?;
    push_visual_surface_view_class_gallery_reports(game_dir, out_dir, &atlas, ctx, &mut reports)?;

    // `systems/intro.md §3`: this case used to be labelled
    // "intro-menu" while rendering the title phase, because a Menu
    // panel with an unfinished flourish takes the title branch. Name
    // it for what it is and seed a mid-flourish step, which exercises
    // the packed/centred band fill, the odd-frame mirror-and-shift,
    // and frame 5's never-revealed row 29 in one frame.
    reports.push(write_visual_intro_flourish_report(
        out_dir,
        "intro-title-flourish",
        "intro title flourish",
        VISUAL_SUITE_FLOURISH_STEP,
        game_dir,
        raster_depth,
    )?);
    reports.push(write_visual_intro_presents_hold_report(
        out_dir,
        "intro-title-presents-hold",
        "intro title presents hold",
        game_dir,
        raster_depth,
    )?);
    reports.push(write_visual_intro_report_with_title_dismissed(
        out_dir,
        "intro-finished-menu",
        "intro finished menu",
        game_dir,
        raster_depth,
    )?);
    // `chargen.md §5.1` steps 1-4. These three cases are the headless
    // coverage for the shared name/gender prompt screen; the CREATE
    // panel screens past step 4 still need the resident proportional
    // width table (cleak/u5-spec#70).
    for (label, typed, submit_name, gender_key) in [
        ("intro-chargen-name-prompt", "AVATAR", false, None),
        ("intro-chargen-gender-prompt", "AVATAR", true, None),
        ("intro-chargen-gender-echo", "AVATAR", true, Some(b'M')),
    ] {
        let records = load_question_records(game_dir)?
            .ok_or_else(|| io::Error::other("visual frame suite requires QUESTION.DAT"))?;
        let mut session = ChargenSession::new(records.records, visual_chargen_rng_pool())?;
        let mut input_line = String::new();
        if submit_name {
            session.submit_name(typed);
            if let Some(key) = gender_key {
                // Step 4's accepted-key echo. `submit_gender_key`
                // moves the session on to step 5, so this frame is
                // painted from the prompt screen directly - in normal
                // play the gypsy panel overdraws it with no wait.
                session.submit_gender_key(key);
            }
        } else {
            input_line.push_str(typed);
        }
        reports.push(write_visual_chargen_prompt_report(
            out_dir,
            label,
            "intro chargen prompt",
            &session,
            &input_line,
            game_dir,
            raster_depth,
        )?);
    }

    let records = load_story_records(game_dir)?
        .ok_or_else(|| io::Error::other("visual frame suite requires STORY.DAT"))?;
    // One PNG per intro story step, so the published paragraph layout can be
    // compared against captures of the original slide by slide. Step 6 is
    // included: it renders the published inline doorway lines
    // (`systems/intro.md §10.1`) instead of a STORY.DAT record.
    for step in 0..INTRO_STORY_STEP_COUNT {
        reports.push(write_visual_intro_report(
            out_dir,
            &format!("intro-story-{step:02}"),
            "intro story step",
            VisualIntroPanel::Story {
                records: records.clone(),
                step,
                transition: None,
            },
            game_dir,
            raster_depth,
        )?);
    }
    // `u4-transfer.md §6` (`cleak/u5-spec#73`): the transfer preview's
    // two published pages - the "Found" summary and the two-panel
    // comparison screen with its first stage highlighted. The source
    // record is synthetic (see `u4_transfer::frame_suite_screen`).
    for (label, keys) in [
        ("intro-u4-transfer-found", 0),
        ("intro-u4-transfer-panels", 1),
    ] {
        let mut screen = u4_transfer::frame_suite_screen(game_dir.to_path_buf());
        for _ in 0..keys {
            let _ = screen.step(' ');
        }
        reports.push(write_visual_intro_report(
            out_dir,
            label,
            "intro u4 transfer preview",
            VisualIntroPanel::U4Transfer {
                screen: Box::new(screen),
            },
            game_dir,
            raster_depth,
        )?);
    }

    // `systems/intro.md §11.2` (`cleak/u5-spec#72`): one PNG per moving
    // phase of the acknowledgement path, so the pillar rise, the
    // outward part sweep, the finished credits page and the inward close
    // sweep are all covered by the visual regression set. The credits
    // themselves are artwork - nothing here is authored text.
    for (label, part_ticks, close_ticks) in [
        ("intro-acknowledgements-risen", 0usize, None),
        (
            "intro-acknowledgements-parting",
            ACK_PART_STEP_COUNT / 2,
            None,
        ),
        ("intro-acknowledgements-credits", ACK_PART_STEP_COUNT, None),
        (
            "intro-acknowledgements-closing",
            ACK_PART_STEP_COUNT,
            // Late enough that the rebuilt menu has reached the label
            // columns; a half-way close frame is still pixel-identical to
            // the half-way part frame, because the outer columns the two
            // phases have published so far carry the same chrome.
            Some(ACK_CLOSE_STEP_COUNT - 3),
        ),
    ] {
        reports.push(write_visual_acknowledgements_report(
            out_dir,
            label,
            part_ticks,
            close_ticks,
            game_dir,
            raster_depth,
        )?);
    }

    let preview = visual_return_to_view_summary(game_dir, raster_depth);
    reports.push(write_visual_intro_report(
        out_dir,
        "intro-return-to-view",
        "intro return-to-view",
        VisualIntroPanel::ReturnToView {
            preview_frames: preview.frames,
            frame_metadata: preview.frame_metadata,
            preview_frame_index: 0,
        },
        game_dir,
        raster_depth,
    )?);

    for report in &reports {
        if report.nonblack_pixels == 0 {
            return Err(io::Error::other(format!(
                "visual frame suite `{}` produced an all-black PNG",
                report.label
            )));
        }
    }
    write_visual_frame_suite_manifest(out_dir, &reports)?;
    Ok(reports)
}

pub fn visual_route_suite(
    game_dir: &Path,
    raster_depth: TileGraphicsDepth,
    out_dir: &Path,
) -> io::Result<Vec<VisualFrameReport>> {
    u5_runtime::test_fixtures::assert_writable_game_dir(out_dir, "visual route suite output");
    std::fs::create_dir_all(out_dir)?;
    let atlas = load_tile_atlas(game_dir, raster_depth)?;
    let font = load_ibm_ch_font(game_dir)?;
    let runes = load_runes_ch_font(game_dir)?;
    let ctx = PlayFrameContext {
        ibm: &font,
        runes: &runes,
        game_dir,
        cursor_frame: 0,
    };
    let mut reports = Vec::new();
    let baseline_brit_ool = std::fs::read(game_dir.join(BRIT_OOL_FILENAME))?;
    let baseline_under_ool = std::fs::read(game_dir.join(UNDER_OOL_FILENAME))?;

    for case in visual_route_suite_cases() {
        std::fs::write(game_dir.join(BRIT_OOL_FILENAME), &baseline_brit_ool)?;
        std::fs::write(game_dir.join(UNDER_OOL_FILENAME), &baseline_under_ool)?;
        let route_game_dir = prepare_visual_route_case_game_dir(game_dir, case.label)?;
        let reload_save_dir = prepare_visual_route_reload_save_dir(game_dir, case.label)?;
        let reload_checkpoints = visual_route_reload_checkpoints(case.label);
        let command_game_dir = route_game_dir.as_deref().unwrap_or(game_dir);
        let mut state = PlayState::load_scene(game_dir, case.options)?;
        if let Some(configure) = case.configure {
            configure(&mut state);
        }
        apply_visual_route_initial_setup(&mut state, case.label, game_dir)?;
        let initial = write_visual_play_report(
            out_dir,
            &visual_route_step_label(case.label, 0, "initial"),
            case.frame_kind,
            &mut state,
            &atlas,
            ctx,
        )?;
        let mut previous_hash = initial.byte_hash;
        reports.push(initial);

        for (index, command) in case.script.iter().enumerate() {
            apply_visual_route_command(&mut state, command, command_game_dir).map_err(|err| {
                io::Error::new(
                    err.kind(),
                    format!(
                        "visual route `{}` step {} command `{command}`: {err}",
                        case.label,
                        index + 1
                    ),
                )
            })?;
            if reload_checkpoints.contains(&(index + 1)) {
                let Some(save_dir) = reload_save_dir.as_deref() else {
                    return Err(io::Error::other(format!(
                        "visual route suite `{}` has reload checkpoints but no temp save dir",
                        case.label
                    )));
                };
                reload_visual_route_state_from_checkpoint(&mut state, game_dir, save_dir)?;
            }
            let report = write_visual_play_report(
                out_dir,
                &visual_route_step_label(case.label, index + 1, command),
                case.frame_kind,
                &mut state,
                &atlas,
                ctx,
            )?;
            if report.byte_hash == previous_hash
                && !visual_route_allows_unchanged_step(case.label, index + 1)
            {
                return Err(io::Error::other(format!(
                    "visual route suite `{}` step {} command `{}` did not change the frame",
                    case.label,
                    index + 1,
                    command
                )));
            }
            previous_hash = report.byte_hash;
            reports.push(report);
        }
        validate_visual_route_final_state(&state, case.label, command_game_dir)?;
        if let Some(dir) = &reload_save_dir {
            let _ = std::fs::remove_dir_all(dir);
        }
        if let Some(dir) = &route_game_dir {
            let _ = std::fs::remove_dir_all(dir);
        }
    }
    std::fs::write(game_dir.join(BRIT_OOL_FILENAME), &baseline_brit_ool)?;
    std::fs::write(game_dir.join(UNDER_OOL_FILENAME), &baseline_under_ool)?;
    push_visual_key_route_reports(game_dir, out_dir, &atlas, ctx, &mut reports)?;

    for report in &reports {
        if report.nonblack_pixels == 0 && !visual_route_frame_is_intentionally_black(&report.label)
        {
            return Err(io::Error::other(format!(
                "visual route suite `{}` produced an all-black PNG",
                report.label
            )));
        }
    }
    std::fs::write(game_dir.join(BRIT_OOL_FILENAME), &baseline_brit_ool)?;
    std::fs::write(game_dir.join(UNDER_OOL_FILENAME), &baseline_under_ool)?;
    write_visual_frame_suite_manifest(out_dir, &reports)?;
    Ok(reports)
}

fn validate_visual_route_final_state(
    state: &PlayState,
    label: &str,
    game_dir: &Path,
) -> io::Result<()> {
    match label {
        "route-castle-canonical-ool-exit" => {
            if state.area
                != (u5_runtime::Area::World {
                    plane: WorldPlane::Britannia,
                })
                || (state.player.x, state.player.y) != (86, 107)
                || state.return_world.is_some()
            {
                return Err(io::Error::other(
                    "canonical-OOL town-exit visual route missed the fixed Britannia return",
                ));
            }
            return Ok(());
        }
        "route-castle-jimmy-magic-lock-no-picker" => {
            if state.turn != 1
                || state.keys != DEFAULT_KEY_STOCK - 1
                || state.prng_state != 0x3456
                || state.active_jimmy.is_some()
                || state.grid[TOWN_GRID_SIDE + 2] != TOWN_DOOR_MAGIC_PLAIN_TILE
                || state.message != "Key broke!"
            {
                return Err(io::Error::other(
                    "Jimmy magic-lock visual route did not take the promptless key-break path",
                ));
            }
            return Ok(());
        }
        "route-castle-jimmy-empty-restraint-no-picker" => {
            if state.turn != 1
                || state.keys != DEFAULT_KEY_STOCK
                || state.prng_state != 0x3456
                || state.active_jimmy.is_some()
                || state.grid[TOWN_GRID_SIDE + 2] != JIMMY_STOCKS_TILE
                || state.message != "No one is there!"
            {
                return Err(io::Error::other(
                    "empty-restraint visual route did not stop before picker and PRNG",
                ));
            }
            return Ok(());
        }
        "route-castle-jimmy-prisoner-release" => {
            let released = state.npcs.iter().find(|npc| npc.slot == 1);
            if state.turn != 1
                || state.keys != DEFAULT_KEY_STOCK
                || state.moral_standing != MORAL_STANDING_MAX
                || state.removed_town_npc_flags.get(&17).copied().unwrap_or(0) & 0b10 == 0
                || state.grid[TOWN_GRID_SIDE + 2] != JIMMY_MANACLES_TILE
                || released.is_none_or(|npc| {
                    npc.dialog_id != NPC_DIALOG_ID_NONE
                        || npc.schedule[NPC_SCHEDULE_AI_OFFSET
                            ..NPC_SCHEDULE_AI_OFFSET + NPC_SCHEDULE_WAYPOINT_COUNT]
                            .iter()
                            .any(|mode| *mode != JIMMY_RELEASE_AI_MODE)
                })
                || state.active_jimmy.is_some()
                || state.message != "I thank thee!"
            {
                return Err(io::Error::other(
                    "prisoner-release visual route did not preserve the live release mutation, reward, and dialogue-gated contact",
                ));
            }
            return Ok(());
        }
        "route-reload-castle-jimmy-prisoner-release" => {
            if state.turn != 1
                || state.keys != DEFAULT_KEY_STOCK
                || state.moral_standing != MORAL_STANDING_MAX
                || state.removed_town_npc_flags.get(&17).copied().unwrap_or(0) & 0b10 == 0
            {
                return Err(io::Error::other(
                    "prisoner-release visual route did not preserve its native removal mask and reward across reload",
                ));
            }
            return Ok(());
        }
        "route-dungeon-jimmy-no-keys-commits-action"
        | "route-dungeon-jimmy-no-lock-commits-action"
        | "route-dungeon-jimmy-cancel-commits-action"
        | "route-dungeon-jimmy-success-clears-trap-subtype" => {
            let index = dungeon_cell_index(
                state.current_floor().unwrap_or(0) as u8,
                state.player.x,
                state.player.y,
            );
            let expected = match label {
                "route-dungeon-jimmy-no-keys-commits-action" => {
                    state.keys == 0
                        && state.grid[index] == 0x4b
                        && state.prng_state == 0x1234
                        && state.message == "No keys!"
                }
                "route-dungeon-jimmy-no-lock-commits-action" => {
                    state.keys == 2
                        && state.grid[index] == 0x00
                        && state.prng_state == 0x1234
                        && state.message == "No lock!"
                }
                "route-dungeon-jimmy-cancel-commits-action" => {
                    state.keys == 2
                        && state.grid[index] == 0x4b
                        && state.prng_state == 0x1234
                        && state.message == "None!"
                }
                "route-dungeon-jimmy-success-clears-trap-subtype" => {
                    state.keys == 2
                        && state.grid[index] == 0x78
                        && state.prng_state == u5_prng_advance_state(0x1234)
                        && state.message == "Unlocked!"
                }
                _ => unreachable!("grouped Jimmy visual-route labels are exhaustive"),
            };
            if state.turn != 1 || state.active_jimmy.is_some() || !expected {
                return Err(io::Error::other(format!(
                    "visual route `{label}` missed the committed dungeon Jimmy outcome"
                )));
            }
            return Ok(());
        }
        "route-dungeon-sjog-underfoot-open" | "route-dungeon-open-chest-spell" => {
            let index = dungeon_cell_index(
                state.current_floor().unwrap_or(0) as u8,
                state.player.x,
                state.player.y,
            );
            let expected_message = if label == "route-dungeon-open-chest-spell" {
                state.spell_charges[OPEN_SPELL_INDEX] == 0
                    && state.party.first().is_some_and(|member| member.mana == 0)
                    && state.message.contains("Safely opened dungeon chest")
            } else {
                state.message.contains("Opened dungeon chest")
            };
            if state.turn != 1 || state.grid[index] != 0x78 || !expected_message {
                return Err(io::Error::other(format!(
                    "visual route `{label}` did not clear dungeon chest trap/subtype bits while preserving the visit marker"
                )));
            }
            return Ok(());
        }
        "route-ship-xit-launches-skiff" => {
            let parked_ship = state.active_objects.iter().skip(1).find(|object| {
                object.type_byte == FIRST_PLAYABLE_FRIGATE_TILE
                    && object.x == state.player.x
                    && object.y == state.player.y
                    && object.z == WorldPlane::Britannia.save_floor()
            });
            if state.turn != 2
                || !matches!(state.player.transport, TransportState::Skiff { .. })
                || parked_ship.is_none_or(|object| {
                    object.aux1 != FIRST_PLAYABLE_FULL_SHIP_HULL || object.aux3 != 1
                })
            {
                return Err(io::Error::other(
                    "ship X-it visual route did not launch a skiff while parking the decremented ship hull",
                ));
            }
            return Ok(());
        }
        "route-ship-xit-no-skiffs-refusal" => {
            if state.turn != 0
                || !matches!(
                    state.player.transport,
                    TransportState::Ship {
                        sails_hoisted: false,
                        hull: FIRST_PLAYABLE_FULL_SHIP_HULL,
                        skiffs: 0,
                        ..
                    }
                )
                || state.message != SHIP_NO_SKIFFS_WARNING
            {
                return Err(io::Error::other(
                    "ship X-it visual route did not preserve the furled ship on the published no-skiffs refusal",
                ));
            }
            return Ok(());
        }
        "route-ship-yell-toggles-town-band" | "route-ship-yell-toggles-dungeon-band" => {
            let expected_scene = if label == "route-ship-yell-toggles-town-band" {
                0x11
            } else {
                0x21
            };
            if state.current_scene_byte() != expected_scene
                || state.turn != 1
                || !state.player.transport.is_ship_under_sail()
                || state.message != YELL_SAILS_HOISTED_MESSAGE
            {
                return Err(io::Error::other(format!(
                    "visual route `{label}` did not take the published low-scene-byte sail shortcut"
                )));
            }
            return Ok(());
        }
        "route-britannia-empty-yell-is-acted" => {
            if state.turn != 1
                || state.active_yell.is_some()
                || state.message != YELL_NOTHING_SAID_MESSAGE
            {
                return Err(io::Error::other(
                    "empty-Yell visual route did not commit the prompted action",
                ));
            }
            return Ok(());
        }
        _ => {}
    }
    if label == "route-world-defeat-persists-ool-before-rescue" {
        let rescue_scene = Scene::new(BLACKTHORN_RESCUE_HANDOFF_SCENE)?;
        let bytes = std::fs::read(game_dir.join(BRIT_OOL_FILENAME))?;
        let offset = 31 * OOL_RECORD_LEN;
        let expected = [0x71, 0x72, 73, 74, 0, 0x75, 0x76, 0x77];
        if state.area
            != (u5_runtime::Area::Town {
                scene: rescue_scene,
                floor: 0,
            })
            || state.turn != 0
            || state.party.is_empty()
            || state
                .party
                .iter()
                .any(|member| member.status != b'G' || member.hp != member.max_hp.max(1))
            || state.player.transport != TransportState::Foot
            || bytes.get(offset..offset + OOL_RECORD_LEN) != Some(expected.as_slice())
        {
            return Err(io::Error::other(
                "world-defeat visual route did not persist the complete live Britannia OOL table before the shared rescue",
            ));
        }
        return Ok(());
    }
    if label != "route-stonegate-trapdoor-rescue" {
        return Ok(());
    }
    let rescue_scene = Scene::new(BLACKTHORN_RESCUE_HANDOFF_SCENE)?;
    if state.area
        != (u5_runtime::Area::Town {
            scene: rescue_scene,
            floor: 0,
        })
        || state.turn != 1
        || state.party.is_empty()
        || state
            .party
            .iter()
            .any(|member| member.status != b'G' || member.hp != member.max_hp.max(1))
        || state.player.transport != TransportState::Foot
    {
        return Err(io::Error::other(format!(
            "Stonegate visual route did not complete one trapdoor turn followed by the shared rescue: area={}, turn={}, party={:?}, transport={:?}, modal={}, capability={:?}",
            state.current_area_label(),
            state.turn,
            state
                .party
                .iter()
                .map(|member| (member.status, member.hp, member.max_hp))
                .collect::<Vec<_>>(),
            state.player.transport,
            visual_modal_prompt_active(state),
            state.party_capability(),
        )));
    }
    Ok(())
}

fn apply_visual_route_initial_setup(
    state: &mut PlayState,
    label: &str,
    game_dir: &Path,
) -> io::Result<()> {
    if let Some(index) = visual_route_public_location_index(label) {
        let Some(entry) = published_world_location_entries().into_iter().nth(index) else {
            return Err(io::Error::other(format!(
                "visual route `{label}` does not map to a published location row"
            )));
        };
        state.area = u5_runtime::Area::World { plane: entry.plane };
        state.player.x = entry.x;
        state.player.y = entry.y;
        if let Some(tile) = entry.expected_tile {
            state.grid[u5_runtime::world_cell_index(entry.x, entry.y)] = tile;
        }
        if let Some(object) = state.active_objects.get_mut(0) {
            object.z = entry.plane.save_floor();
        }
        state.sync_player_object();
        state.mark_visibility_dirty();
        return Ok(());
    }
    // Legacy labels retained for manifest stability. They now seed authentic
    // published rows because E-Enter no longer honors a debug-target bypass.
    if let Some(index) = match label {
        "route-debug-enter-castle" | "route-debug-enter-castle-return-world" => Some(16),
        "route-debug-enter-castle-from-underworld" => Some(24),
        "route-debug-enter-dungeon" => Some(32),
        _ => None,
    } {
        let entry = published_world_location_entries()
            .into_iter()
            .nth(index)
            .expect("legacy entry route maps to a published row");
        state.area = u5_runtime::Area::World { plane: entry.plane };
        state.player.x = entry.x;
        state.player.y = entry.y;
        if let Some(tile) = entry.expected_tile {
            state.grid[u5_runtime::world_cell_index(entry.x, entry.y)] = tile;
        }
        if let Some(object) = state.active_objects.get_mut(0) {
            object.z = entry.plane.save_floor();
        }
        state.sync_player_object();
        state.mark_visibility_dirty();
        return Ok(());
    }
    if let Some(virtue) = visual_route_shrine_virtue(label) {
        seed_visual_route_shrine(state, virtue);
        return Ok(());
    }
    match label {
        "route-endgame-missing-box-terminal-jitter"
        | "route-endgame-missing-box-confirmation"
        | "route-endgame-box-victory-confirmation"
        | "route-endgame-box-full-victory-cinematic"
        | "route-endgame-class-tableau-restoration"
        | "route-endgame-tableau-walk-in" => {
            state.enter_endgame_from_game_dir(Some(game_dir))?;
        }
        "route-codex-urn-honesty-read" => {
            seed_visual_route_shrine(state, ShrineVirtue::Honesty);
            state.shrine_ordained_mask = ShrineVirtue::Honesty.bit();
            state.shrine_codex_mask = 0;
        }
        "route-shrine-honesty-codex-turn-in" => {
            seed_visual_route_shrine(state, ShrineVirtue::Honesty);
            state.shrine_ordained_mask = ShrineVirtue::Honesty.bit();
            state.shrine_codex_mask = ShrineVirtue::Honesty.bit();
            state.moral_standing = 10;
        }
        "route-shrine-compassion-completed-offering" => {
            seed_visual_route_shrine(state, ShrineVirtue::Compassion);
            state.shrine_ordained_mask = 0;
            state.shrine_codex_mask = ShrineVirtue::Compassion.bit();
            state.moral_standing = 10;
        }
        "route-castle-jimmy-magic-lock-no-picker" => {
            seed_visual_route_jimmy_unoccupied_target(state, TOWN_DOOR_MAGIC_PLAIN_TILE);
            state.party[0].climb_stat = 0;
            state.prng_state = 0x3456;
        }
        "route-castle-jimmy-empty-restraint-no-picker" => {
            seed_visual_route_jimmy_unoccupied_target(state, JIMMY_STOCKS_TILE);
            state.party[0].climb_stat = 0;
            state.prng_state = 0x3456;
        }
        "route-castle-jimmy-prisoner-release" | "route-reload-castle-jimmy-prisoner-release" => {
            seed_visual_route_jimmy_prisoner(state);
        }
        _ => {}
    }
    Ok(())
}

fn push_visual_key_route_reports(
    game_dir: &Path,
    out_dir: &Path,
    atlas: &TileAtlas,
    ctx: PlayFrameContext<'_>,
    reports: &mut Vec<VisualFrameReport>,
) -> io::Result<()> {
    for case in visual_key_route_suite_cases() {
        let mut state = PlayState::load_scene(game_dir, case.options)?;
        if let Some(configure) = case.configure {
            configure(&mut state);
        }
        let mut input_line = String::new();
        let mut prompt_cursor_visible = visual_line_prompt_active(&state);
        let initial = write_visual_play_report_with_input(
            out_dir,
            &visual_route_step_label(case.label, 0, "initial"),
            case.frame_kind,
            &mut state,
            atlas,
            ctx,
            &input_line,
            prompt_cursor_visible,
        )?;
        let mut previous_hash = initial.byte_hash;
        reports.push(initial);

        for (index, step) in case.steps.iter().enumerate() {
            apply_visual_key_route_step(&mut state, &mut input_line, *step, game_dir)?;
            prompt_cursor_visible = visual_line_prompt_active(&state);
            let report = write_visual_play_report_with_input(
                out_dir,
                &visual_key_route_step_label(case.label, index + 1, step),
                case.frame_kind,
                &mut state,
                atlas,
                ctx,
                &input_line,
                prompt_cursor_visible,
            )?;
            if report.byte_hash == previous_hash {
                return Err(io::Error::other(format!(
                    "visual key route suite `{}` step `{}` did not change the frame",
                    case.label, step.label
                )));
            }
            previous_hash = report.byte_hash;
            reports.push(report);
        }
    }
    Ok(())
}

fn apply_visual_key_route_step(
    state: &mut PlayState,
    input_line: &mut String,
    step: VisualKeyStep,
    game_dir: &Path,
) -> io::Result<()> {
    if visual_line_prompt_active(state) {
        match handle_visual_line_key(
            state,
            input_line,
            step.key,
            step.shift,
            step.control,
            game_dir,
        )? {
            Some(PlayInputDisposition::Quit) => {
                return Err(io::Error::other(format!(
                    "visual key route step `{}` requested quit",
                    step.label
                )));
            }
            Some(PlayInputDisposition::Continue) | None => return Ok(()),
        }
    }
    if step.key == KeyCode::Escape && escape_is_inert_in_gameplay(state) {
        // The shell swallows Escape outside a prompt; the route replays the
        // same nothing rather than dispatching a byte the shell never sends.
        return Ok(());
    }
    let Some(ch) = key_code_to_char(step.key, step.shift, step.control) else {
        return Ok(());
    };
    match handle_play_key_input(state, ch, "", game_dir)? {
        PlayInputDisposition::Quit => Err(io::Error::other(format!(
            "visual key route step `{}` requested quit",
            step.label
        ))),
        PlayInputDisposition::Continue => Ok(()),
    }
}

fn visual_key_route_step_label(route_label: &str, step: usize, key: &VisualKeyStep) -> String {
    visual_route_step_label(route_label, step, key.label)
}

fn seed_visual_key_route_conversation(state: &mut PlayState) {
    fn enc(text: &str) -> Vec<u8> {
        text.bytes().map(|byte| byte ^ TLK_TEXT_XOR_MASK).collect()
    }
    let raw = vec![
        enc("Ada"),
        enc("a quiet smith"),
        enc("Greetings, traveller."),
        enc("I mend gear."),
        enc("Farewell."),
    ];
    let decoded = vec![
        "Ada".to_string(),
        "a quiet smith".to_string(),
        "Greetings, traveller.".to_string(),
        "I mend gear.".to_string(),
        "Farewell.".to_string(),
    ];
    state.active_conversation = Some(Box::new(ConversationSession::new(raw, decoded)));
    state.advance_active_conversation_greeting();
}

fn seed_visual_key_route_shrine(state: &mut PlayState) {
    seed_visual_route_shrine(state, ShrineVirtue::Honesty);
}

fn seed_visual_key_route_reagent_shop(state: &mut PlayState) {
    state.gold = 100;
    state.reagents = [0; REAGENT_COUNT];
    state.active_shop = Some(ActiveShopSession::Reagent(ReagentShopState::for_herbalist(
        Herbalist::Mysticism,
    )));
}

fn seed_visual_key_route_ready_picker(state: &mut PlayState) {
    state.party_strengths = vec![50];
    state.party_equipment = default_party_equipment(1);
    state.equipment_stock[EQUIPMENT_ID_BOW] = 1;
    state.equipment_stock[EQUIPMENT_ID_ARROWS] = 5;
}

fn seed_visual_key_route_use_picker(state: &mut PlayState) {
    state.clock = GameClock::with_date(139, 1, 1, 13, 0).expect("visual route clock is valid");
    state.special_items[SPECIAL_ITEM_POCKET_WATCH_INDEX] = 1;
}

fn seed_visual_key_route_mix_prompt(state: &mut PlayState) {
    state.reagents = [0; REAGENT_COUNT];
    state.reagents[REAGENT_SULFUR_ASH] = 2;
}

fn seed_visual_key_route_rest_watch(state: &mut PlayState) {
    state.clock = GameClock::new(8, 0).expect("visual route clock is valid");
    state.party.push(PartyMember {
        slot: 1,
        class_byte: b'B',
        status: b'G',
        climb_stat: DEFAULT_CLIMB_STAT,
        mana: 0,
        hp: 8,
        max_hp: 12,
        level: 8,
    });
}

fn seed_visual_key_route_new_order(state: &mut PlayState) {
    state.party.push(PartyMember {
        slot: 1,
        class_byte: b'F',
        status: b'G',
        climb_stat: DEFAULT_CLIMB_STAT,
        mana: 0,
        hp: 20,
        max_hp: 20,
        level: 1,
    });
    state.party.push(PartyMember {
        slot: 2,
        class_byte: b'M',
        status: b'G',
        climb_stat: DEFAULT_CLIMB_STAT,
        mana: 4,
        hp: 18,
        max_hp: 18,
        level: 2,
    });
    state.party_names = vec![*b"AVATAR\0\0\0", *b"IOLO\0\0\0\0\0", *b"MARIA\0\0\0\0"];
}

fn visual_route_public_location_index(label: &str) -> Option<usize> {
    let suffix = label.strip_prefix("route-stock-location-enter-")?;
    let row = suffix.parse::<usize>().ok()?;
    (1..=published_world_location_entries().len())
        .contains(&row)
        .then_some(row - 1)
}

fn seed_visual_route_shrine(state: &mut PlayState, virtue: ShrineVirtue) {
    state.area = u5_runtime::Area::World {
        plane: WorldPlane::Britannia,
    };
    state.player.x = 62;
    state.player.y = 124;
    state.player.facing = Direction::East;
    let tile = SHRINE_ALTAR_TILE_FIRST + virtue.index() as u8;
    let idx = u5_runtime::world_cell_index(state.player.x, state.player.y);
    if let Some(cell) = state.grid.get_mut(idx) {
        *cell = tile;
    }
    state.sync_player_object();
    state.mark_visibility_dirty();
}

fn visual_route_shrine_virtue(label: &str) -> Option<ShrineVirtue> {
    let key = label
        .strip_prefix("route-shrine-native-")?
        .strip_suffix("-meditation")?;
    ShrineVirtue::from_key(key)
}

fn prepare_visual_route_case_game_dir(
    game_dir: &Path,
    case_label: &str,
) -> io::Result<Option<PathBuf>> {
    if case_label != "route-codex-urn-honesty-read"
        && case_label != "route-world-defeat-persists-ool-before-rescue"
    {
        return Ok(None);
    }
    let dir = visual_route_temp_dir(case_label, "case")?;
    if case_label == "route-world-defeat-persists-ool-before-rescue" {
        for file_name in [BRIT_DAT_FILENAME, "CASTLE.DAT", "CASTLE.NPC", "CASTLE.TLK"] {
            u5_runtime::test_fixtures::copy_asset_writable(
                &game_dir.join(file_name),
                &dir.join(file_name),
            )?;
        }
        let karma = game_dir.join("KARMA.DAT");
        if karma.exists() {
            u5_runtime::test_fixtures::copy_asset_writable(&karma, &dir.join("KARMA.DAT"))?;
        }
    }
    if case_label == "route-codex-urn-honesty-read" {
        std::fs::write(
            dir.join(CODEX_URN_TABLE_FILE),
            format!("BRITANNIA 62 124 {SHRINE_ALTAR_TILE_FIRST}\n"),
        )?;
    }
    Ok(Some(dir))
}

fn prepare_visual_route_reload_save_dir(
    game_dir: &Path,
    case_label: &str,
) -> io::Result<Option<PathBuf>> {
    if visual_route_reload_checkpoints(case_label).is_empty() {
        return Ok(None);
    }
    let dir = visual_route_temp_dir(case_label, "reload")?;
    seed_visual_route_save_files(game_dir, &dir)?;
    Ok(Some(dir))
}

fn visual_route_temp_dir(case_label: &str, label: &str) -> io::Result<PathBuf> {
    let nonce = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_nanos())
        .unwrap_or(0);
    let dir = std::env::temp_dir().join(format!(
        "u5-visual-route-{case_label}-{label}-{}-{nonce}",
        std::process::id()
    ));
    std::fs::create_dir_all(&dir)?;
    Ok(dir)
}

fn seed_visual_route_save_files(game_dir: &Path, save_dir: &Path) -> io::Result<()> {
    if copy_visual_route_save_file(game_dir, save_dir, SAVED_GAM_FILENAME, SAVED_GAM_FILENAME)
        .is_err()
    {
        copy_visual_route_save_file(game_dir, save_dir, "INIT.GAM", SAVED_GAM_FILENAME)?;
    }
    if copy_visual_route_save_file(game_dir, save_dir, SAVED_OOL_FILENAME, SAVED_OOL_FILENAME)
        .is_err()
    {
        if game_dir.join("INIT.OOL").exists() {
            let init_ool = std::fs::read(game_dir.join("INIT.OOL"))?;
            let mut saved_ool = vec![0; SAVED_OOL_LEN];
            let copied_len = init_ool.len().min(saved_ool.len() / 2);
            saved_ool[..copied_len].copy_from_slice(&init_ool[..copied_len]);
            std::fs::write(save_dir.join(SAVED_OOL_FILENAME), saved_ool)?;
        } else {
            std::fs::write(save_dir.join(SAVED_OOL_FILENAME), vec![0; SAVED_OOL_LEN])?;
        }
    }
    // Reload checkpoints perform a real Q-save. The published save flow reads
    // both per-plane mirrors rather than deriving them from SAVED.OOL, so the
    // isolated writable fixture must carry the complete four-file contract.
    let saved_ool = std::fs::read(save_dir.join(SAVED_OOL_FILENAME))?;
    u5_runtime::write_saved_ool_mirrors(save_dir, &saved_ool)?;
    Ok(())
}

fn copy_visual_route_save_file(
    game_dir: &Path,
    save_dir: &Path,
    source_name: &str,
    destination_name: &str,
) -> io::Result<()> {
    // The reload checkpoints write into `save_dir`, so the seeded copy
    // must not inherit the pristine install's read-only attribute.
    u5_runtime::test_fixtures::copy_asset_writable(
        &game_dir.join(source_name),
        &save_dir.join(destination_name),
    )
}

fn visual_route_reload_checkpoints(case_label: &str) -> &'static [usize] {
    match case_label {
        "route-reload-boarded-horse-pass"
        | "route-reload-gate-travel-underworld-pass"
        | "route-reload-chasm-underworld-pass"
        | "route-reload-ship-xit-skiff-pass"
        | "route-reload-dungeon-ladder-down-up"
        | "route-reload-dungeon-ladder-down-up-route"
        | "route-reload-dungeon-surface-exit-return-world" => &[1],
        "route-reload-underworld-fixed-hidden-stack-search-get-search"
        | "route-reload-horse-trader-horse-and-rider-buy-pass" => &[2],
        "route-reload-castle-jimmy-prisoner-release" => &[3],
        _ => &[],
    }
}

fn reload_visual_route_state_from_checkpoint(
    state: &mut PlayState,
    game_dir: &Path,
    save_dir: &Path,
) -> io::Result<()> {
    state.save_game_command(save_dir, Some(true))?;
    let options = load_play_options_from_save(save_dir)?;
    *state = PlayState::load_scene(game_dir, options)?;
    Ok(())
}

