    #[test]
    fn intro_start_menu_reveal_is_one_blocking_dissolve_of_the_published_rect() {
        // `cleak/u5-spec#53`: the one-pixel-column-per-title-tick
        // sweep is withdrawn in full for both intro callers. The
        // reveal is the driver's rectangle dissolve — a single
        // blocking transfer that visits every pixel of
        // `(0, 0)..(319, 100)` exactly once and returns, with no
        // per-column schedule and no tick pacing.
        assert_eq!(INTRO_START_MENU_REVEAL_RECT, (0, 0, 319, 100));
        let (x0, y0, x1, y1) = INTRO_START_MENU_REVEAL_RECT;

        let mut source = new_intro_display_buffer();
        for (index, pixel) in source.pixels.iter_mut().enumerate() {
            *pixel = (index % 15 + 1) as u8;
        }
        let mut destination = new_intro_display_buffer();
        destination.clear(0);

        let copied = destination.dissolve_rect_from(&source, INTRO_START_MENU_REVEAL_RECT);

        let width = usize::from(x1 - x0) + 1;
        let height = usize::from(y1 - y0) + 1;
        assert_eq!(
            copied,
            width * height,
            "every pixel is visited exactly once"
        );
        for y in 0..INTRO_FRAMEBUFFER_HEIGHT as usize {
            for x in 0..INTRO_FRAMEBUFFER_WIDTH as usize {
                let index = y * destination.width + x;
                let inside = (usize::from(y0)..=usize::from(y1)).contains(&y)
                    && (usize::from(x0)..=usize::from(x1)).contains(&x);
                let expected = if inside { source.pixels[index] } else { 0 };
                assert_eq!(destination.pixels[index], expected, "({x}, {y})");
            }
        }
    }

    #[test]
    fn intro_start_menu_reveal_copies_first_pixel_before_odd_visit_abort_poll() {
        // `cleak/u5-spec#122`: the zero-initialized phase polls visits
        // 1, 3, 5, ... after copying. A key pending at entry therefore
        // transfers exactly the walk's first coordinate `(1, 0)`.
        let mut source = new_intro_display_buffer();
        source.clear(9);
        let mut destination = new_intro_display_buffer();
        destination.clear(0);

        let report = destination.dissolve_rect_from_with_pending_key(
            &source,
            INTRO_START_MENU_REVEAL_RECT,
            u5_runtime::DissolveAbortGate::on_driver_load(),
            true,
        );

        assert_eq!(report.copied_pixels, 1);
        assert_eq!(report.aborted_after, Some((1, 0)));
        assert_eq!(destination.pixels[1], 9);
        assert_eq!(
            destination
                .pixels
                .iter()
                .filter(|pixel| **pixel == 9)
                .count(),
            1
        );
    }

    #[test]
    fn intro_rect_dissolve_order_satisfies_the_published_visit_contract() {
        // `systems/display-driver-abi.md §9.6` publishes four visible
        // bullets for dispatch `0x66`. The original drives the order
        // from a Galois-style LFSR whose tap inventory is indexed by
        // the rectangle's pixel count, but §9.6 states outright that
        // "an engine that does not need exact frame-by-frame parity
        // may substitute any other order that satisfies the four
        // bullet points above" — so this test pins the four bullets
        // and stays agnostic about which generator supplies them.
        let (width, height) = (32usize, 16usize);
        let rect = u5_runtime::DisplayPixelRect {
            x0: 0,
            y0: 0,
            x1: width - 1,
            y1: height - 1,
        };
        let walk = || {
            let mut state = u5_runtime::EgaDissolveState::new(rect);
            let mut visited = Vec::new();
            while let Some(pixel) = state.next_pixel() {
                visited.push(pixel);
            }
            visited
        };
        let visited = walk();

        // Bullet 1: every pixel inside the inclusive rectangle is
        // visited exactly once.
        assert_eq!(visited.len(), width * height);
        let mut sorted = visited.clone();
        sorted.sort_unstable();
        sorted.dedup();
        assert_eq!(sorted.len(), visited.len(), "every pixel exactly once");
        assert_eq!(sorted.first(), Some(&(0, 0)));
        assert_eq!(sorted.last(), Some(&(width - 1, height - 1)));

        // Bullet 3: deterministic and reproducible across calls with
        // the same rectangle dimensions.
        assert_eq!(walk(), visited, "visit order must be reproducible");

        // Bullet 4: not row-major, not column-major, not a clean
        // spiral; it reads as scattered single-pixel updates.
        let row_major: Vec<(usize, usize)> = (0..height)
            .flat_map(|y| (0..width).map(move |x| (x, y)))
            .collect();
        let column_major: Vec<(usize, usize)> = (0..width)
            .flat_map(|x| (0..height).map(move |y| (x, y)))
            .collect();
        assert_ne!(visited, row_major);
        assert_ne!(visited, column_major);
        let adjacent = visited
            .windows(2)
            .filter(|pair| pair[0].0.abs_diff(pair[1].0) + pair[0].1.abs_diff(pair[1].1) == 1)
            .count();
        assert!(
            adjacent * 4 < visited.len(),
            "dissolve order should be scattered, {adjacent} adjacent steps of {}",
            visited.len()
        );

        // Bullet 2 is covered by
        // `intro_start_menu_reveal_is_one_blocking_dissolve_of_the_published_rect`,
        // which asserts the destination matches the source across the
        // whole rectangle once the transfer returns.
    }

