    #[test]
    fn intro_first_reveal_abort_consumes_key_downgrades_loader_and_keeps_preview() {
        // `cleak/u5-spec#122`: a key first discovered by the logo dissolve
        // is consumed by the loader's immediate read. Only the loader's local
        // animated flag is downgraded: ignition is skipped, the rectangle is
        // completed plainly, and the caller still arms automatic RTV.
        let dir = debug_game_dir();
        install_intro_assets(&dir);
        let mut intro = VisualIntroState {
            game_dir: dir,
            raster_depth: TileGraphicsDepth::Ega16,
            dispatch: UnifiedMenuDispatch::new(),
            title_flourish_step: intro_title_flourish_total_steps(),
            title_flourish_complete: true,
            title_signature_progress: 0,
            title_signature_complete: true,
            title_presents_hold_ticks: 0,
            title_sequence_skipped: false,
            pending_auto_return_to_view: false,
            title_tick_frame: 0,
            title_tick_visible_frame: 0,
            surface: new_intro_display_buffer(),
            modal_backing: None,
            menu_idle_ticks: 0,
            menu_idle_bios_ticks: 0,
            menu_cursor_pass: 0,
            menu_cursor_blanked: false,
            message_waiting_for_key: false,
            message: String::new(),
            panel: VisualIntroPanel::Menu,
            launch_result: Arc::new(Mutex::new(None)),
            image_handle: None,
            font_slots: None,
            text_windows: TextWindowSystem::new(),
            pending_pre_flourish_outcome: None,
            title_tick_frames: None,
            pending_reveal_clicks: Vec::new(),
        };

        let outcome = finish_visual_intro_title_to_menu(&mut intro, true);

        assert_eq!(outcome.animated_after_reveal, false);
        assert!(outcome.reveal_abort_key_consumed);
        // `display-driver-abi.md §9.6`: "a key already pending when the first
        // start/menu dissolve begins leaves exactly one pixel transferred
        // before abort: the first visit, `(1,0)`" — and the abort "completes
        // the current copied pixel and any publication it caused", so that one
        // visit still clicks.
        assert_eq!(outcome.reveal_clicks.len(), 1);
        assert!(matches!(intro.panel, VisualIntroPanel::Menu));
        assert!(!intro.title_sequence_skipped);
        assert!(intro.pending_auto_return_to_view);
        assert_eq!(
            visual_intro_menu_highlight(&intro),
            IntroSubflow::JourneyOnward
        );
        let mut expected = new_intro_display_buffer();
        draw_visual_intro_start_menu_art_to_buffer(
            &mut expected,
            &intro.game_dir,
            intro.raster_depth,
        );
        for y in 0..=100usize {
            let start = y * intro.surface.width;
            let end = start + 320;
            assert_eq!(
                intro.surface.pixels[start..end],
                expected.pixels[start..end]
            );
        }
        let _ = fs::remove_dir_all(&intro.game_dir);
    }

