    #[test]
    fn intro_signature_completion_shows_final_title_before_start_menu() {
        let dir = debug_game_dir();
        install_intro_assets(&dir);
        let signature = load_british_pth(&dir).unwrap();
        let total_steps = british_signature_step_count(&signature);
        assert!(total_steps > 0);
        let mut intro = VisualIntroState {
            game_dir: dir.clone(),
            raster_depth: TileGraphicsDepth::Ega16,
            dispatch: UnifiedMenuDispatch::new(),
            title_flourish_step: intro_title_flourish_total_steps(),
            title_flourish_complete: true,
            title_signature_progress: total_steps - 1,
            title_signature_complete: false,
            title_presents_hold_ticks: 0,
            title_sequence_skipped: false,
            pending_auto_return_to_view: false,
            title_tick_frame: 0,
            title_tick_visible_frame: 0,
            surface: new_intro_display_buffer(),
            modal_backing: None,
            menu_idle_ticks: 17,
            menu_idle_bios_ticks: 0,
            menu_cursor_pass: 0,
            menu_cursor_blanked: false,
            message_waiting_for_key: false,
            message: "stale title message".to_string(),
            panel: VisualIntroPanel::Menu,
            launch_result: Arc::new(Mutex::new(None)),
            image_handle: None,
            font_slots: Some(IntroFontSlots::new(
                load_ibm_ch_font(&dir).expect("intro fixtures require IBM.CH"),
                load_ibm_ch_font(&dir).expect("intro fixtures require IBM.CH"),
            )),
            text_windows: TextWindowSystem::new(),
            pending_pre_flourish_outcome: None,
            title_tick_frames: None,
            pending_reveal_clicks: Vec::new(),
        };

        assert!(advance_visual_intro_animation_tick(&mut intro));

        assert!(intro.title_signature_complete);
        assert_eq!(intro.title_signature_progress, 0);
        assert!(matches!(
            intro.dispatch.tick_title(),
            UnifiedMenuStep::PresentTitle
        ));
        assert_eq!(intro.title_tick_visible_frame, 0);
        assert_eq!(intro.title_tick_frame, 0);
        let final_title = render_intro_frame(&mut intro);
        assert_eq!(
            final_title,
            visual_intro_title_art_buffer(&dir, None, None).to_rgba()
        );

        assert!(advance_visual_intro_animation_tick(&mut intro));

        assert!(matches!(
            intro.dispatch.tick_title(),
            UnifiedMenuStep::PresentTitle
        ));
        let (publish_count, final_counter) = match &intro.panel {
            VisualIntroPanel::SubtitleIgnition { playback, .. } => {
                (playback.publishes.len(), playback.final_frame)
            }
            _ => panic!("animated start/menu path must enter subtitle ignition"),
        };
        assert!(publish_count > 1);
        let ignition_rgba = render_intro_frame(&mut intro);
        assert!(
            ignition_rgba
                .chunks_exact(4)
                .any(|pixel| pixel[0] != 0 || pixel[1] != 0 || pixel[2] != 0)
        );

        for _ in 1..publish_count {
            assert!(advance_visual_intro_animation_tick(&mut intro));
        }
        assert!(matches!(
            intro.panel,
            VisualIntroPanel::SubtitleIgnition { .. }
        ));
        assert!(advance_visual_intro_animation_tick(&mut intro));

        assert!(!matches!(
            intro.dispatch.tick_title(),
            UnifiedMenuStep::PresentTitle
        ));
        assert_eq!(intro.title_tick_visible_frame, final_counter);
        assert_eq!(intro.title_tick_frame, title_tick_next_frame(final_counter));
        assert_eq!(intro.menu_idle_ticks, 0);
        assert!(intro.message.is_empty());
        assert!(intro.pending_auto_return_to_view);
        // After the signature path completes and the menu phase
        // begins, the renderer runs the menu path which routes
        // through `draw_visual_intro_start_menu_to_buffer` plus
        // the placeholder title-tick strip + `cleak/u5-spec#63`
        // placeholder border. The frame must come out non-blank.
        let menu_rgba = render_intro_frame(&mut intro);
        assert!(
            menu_rgba
                .chunks_exact(4)
                .any(|pixel| pixel[0] != 0 || pixel[1] != 0 || pixel[2] != 0),
            "menu render must produce visible pixels through the placeholder strip + frame"
        );
        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn intro_signature_tick_saturates_at_path_length_and_completes() {
        // With SIGNATURE_STEPS_PER_TICK > 1, an in-progress signature
        // tick can land past the path's final byte on the last tick.
        // The advancer saturates progress at total_steps and marks
        // the signature complete; it should not panic.
        let dir = debug_game_dir();
        install_intro_assets(&dir);
        let signature = load_british_pth(&dir).unwrap();
        let total_steps = british_signature_step_count(&signature);
        assert!(total_steps > 0);
        let mut intro = VisualIntroState {
            game_dir: dir.clone(),
            raster_depth: TileGraphicsDepth::Ega16,
            dispatch: UnifiedMenuDispatch::new(),
            title_flourish_step: intro_title_flourish_total_steps(),
            title_flourish_complete: true,
            // Start one stroke shy of the path length so the next
            // tick (which adds SIGNATURE_STEPS_PER_TICK) saturates.
            title_signature_progress: total_steps - 1,
            title_signature_complete: false,
            title_presents_hold_ticks: 0,
            title_sequence_skipped: false,
            pending_auto_return_to_view: false,
            title_tick_frame: 0,
            title_tick_visible_frame: 0,
            surface: new_intro_display_buffer(),
            modal_backing: None,
            menu_idle_ticks: 0,
            menu_idle_bios_ticks: 0,
            menu_cursor_pass: 0,
            menu_cursor_blanked: false,
            message_waiting_for_key: false,
            message: String::new(),
            panel: VisualIntroPanel::Menu,
            launch_result: Arc::new(Mutex::new(None)),
            image_handle: None,
            font_slots: None,
            text_windows: TextWindowSystem::new(),
            pending_pre_flourish_outcome: None,
            title_tick_frames: None,
            pending_reveal_clicks: Vec::new(),
        };

        let advanced = advance_visual_intro_animation_tick(&mut intro);

        assert!(advanced, "saturating tick should still report progress");
        assert!(intro.title_signature_complete);
        assert_eq!(intro.title_signature_progress, 0);
        let _ = fs::remove_dir_all(dir);
    }

