    #[test]
    fn british_signature_renderer_paints_pen_down_steps_from_spec_origins() {
        let mut rgba =
            vec![0; (TITLE_SURFACE_WIDTH as usize) * (TITLE_SURFACE_HEIGHT as usize) * 4];
        for pixel in rgba.chunks_exact_mut(4) {
            pixel.copy_from_slice(&[0x00, 0x00, 0x00, 0xff]);
        }
        let signature = BritishPth {
            segments: vec![
                vec![
                    PenStroke {
                        dx: 1,
                        dy: 0,
                        pen_down: true,
                    },
                    PenStroke {
                        dx: 5,
                        dy: 0,
                        pen_down: false,
                    },
                    PenStroke {
                        dx: 0,
                        dy: 1,
                        pen_down: true,
                    },
                ],
                vec![PenStroke {
                    dx: 0,
                    dy: 1,
                    pen_down: true,
                }],
                vec![PenStroke {
                    dx: -1,
                    dy: 0,
                    pen_down: true,
                }],
                vec![PenStroke {
                    dx: 1,
                    dy: -1,
                    pen_down: false,
                }],
            ],
        };

        draw_british_signature_rgba(
            &mut rgba,
            TITLE_SURFACE_WIDTH as usize,
            TITLE_SURFACE_HEIGHT as usize,
            &signature,
            british_signature_step_count(&signature),
        );
        let width = TITLE_SURFACE_WIDTH as usize;

        assert_eq!(rgba_pixel(&rgba, width, 69, 44), [0xff, 0xff, 0xff, 0xff]);
        assert_eq!(rgba_pixel(&rgba, width, 74, 44), [0, 0, 0, 0xff]);
        assert_eq!(rgba_pixel(&rgba, width, 74, 45), [0xff, 0xff, 0xff, 0xff]);
        assert_eq!(rgba_pixel(&rgba, width, 94, 65), [0xff, 0xff, 0xff, 0xff]);
        assert_eq!(rgba_pixel(&rgba, width, 77, 143), [0xff, 0xff, 0xff, 0xff]);
        assert_eq!(rgba_pixel(&rgba, width, 106, 166), [0, 0, 0, 0xff]);
    }

    #[test]
    fn british_signature_renderer_rejects_progress_past_path_length() {
        let mut rgba =
            vec![0; (TITLE_SURFACE_WIDTH as usize) * (TITLE_SURFACE_HEIGHT as usize) * 4];
        let signature = BritishPth {
            segments: vec![
                vec![PenStroke {
                    dx: 1,
                    dy: 0,
                    pen_down: true,
                }],
                vec![PenStroke {
                    dx: 0,
                    dy: 1,
                    pen_down: true,
                }],
                vec![PenStroke {
                    dx: -1,
                    dy: 0,
                    pen_down: true,
                }],
                vec![PenStroke {
                    dx: 1,
                    dy: -1,
                    pen_down: false,
                }],
            ],
        };
        let requested_steps = british_signature_step_count(&signature) + 1;

        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            draw_british_signature_rgba(
                &mut rgba,
                TITLE_SURFACE_WIDTH as usize,
                TITLE_SURFACE_HEIGHT as usize,
                &signature,
                requested_steps,
            );
        }));

        let payload = result.expect_err("signature progress past the path must panic");
        let message = payload
            .downcast_ref::<String>()
            .map(String::as_str)
            .or_else(|| payload.downcast_ref::<&str>().copied())
            .expect("signature panic payload must be a string");
        assert!(message.contains("BRITISH.PTH contains"), "{message}");
    }

    #[test]
    fn intro_title_art_rejects_active_signature_at_completed_progress() {
        let dir = debug_game_dir();
        install_intro_assets(&dir);
        let signature = load_british_pth(&dir).unwrap();
        let total_steps = british_signature_step_count(&signature);

        let result = std::panic::catch_unwind(|| {
            let _ = visual_intro_title_art_buffer(&dir, None, Some(total_steps));
        });

        let payload = result.expect_err("completed signature progress must use completed phase");
        let message = payload
            .downcast_ref::<String>()
            .map(String::as_str)
            .or_else(|| payload.downcast_ref::<&str>().copied())
            .expect("signature progress panic payload must be a string");
        assert!(
            message.contains("must be less than BRITISH.PTH path length"),
            "{message}"
        );
        let _ = fs::remove_dir_all(dir);
    }

    #[test]
    fn intro_display_title_tick_copies_provided_frames() {
        // `systems/display-driver.md §5` destination contract: each
        // tick copies the active frame's pixels over the full
        // `(0, 65)` `320 x 49` rectangle, overwriting whatever was
        // there (no transparency, no blend). The placeholder frame
        // set is all-zero, so a non-zero background is overwritten
        // to black inside the rectangle and left alone outside.
        let mut buffer = IntroDisplayBuffer::new(
            INTRO_FRAMEBUFFER_WIDTH as usize,
            INTRO_FRAMEBUFFER_HEIGHT as usize,
        );
        buffer.clear(0x03);
        let frames = placeholder_title_tick_frames();
        buffer.draw_title_tick(0, &frames);

        let width = buffer.width;
        let rect_x0 = TITLE_TICK_FRAME_X as usize;
        let rect_y0 = TITLE_TICK_FRAME_Y as usize;
        let rect_x1 = rect_x0 + TITLE_TICK_FRAME_WIDTH as usize - 1;
        let rect_y1 = rect_y0 + TITLE_TICK_FRAME_HEIGHT as usize - 1;
        for y in 0..buffer.height {
            for x in 0..width {
                let inside = (rect_x0..=rect_x1).contains(&x) && (rect_y0..=rect_y1).contains(&y);
                let expected = if inside { 0x00 } else { 0x03 };
                assert_eq!(buffer.pixels[y * width + x], expected, "({x}, {y})");
            }
        }
    }

