    #[test]
    fn visual_intro_summary_rejects_title_text_fallback_then_shows_menu() {
        let mut intro = VisualIntroState {
            game_dir: debug_game_dir(),
            raster_depth: TileGraphicsDepth::Ega16,
            dispatch: UnifiedMenuDispatch::new(),
            title_flourish_step: 0,
            title_flourish_complete: false,
            title_signature_progress: 0,
            title_signature_complete: false,
            title_presents_hold_ticks: 0,
            title_sequence_skipped: false,
            pending_auto_return_to_view: false,
            title_tick_frame: 0,
            title_tick_visible_frame: 0,
            surface: new_intro_display_buffer(),
            modal_backing: None,
            menu_idle_ticks: 0,
            menu_idle_bios_ticks: 0,
            menu_cursor_pass: 0,
            menu_cursor_blanked: false,
            message_waiting_for_key: false,
            message: String::new(),
            panel: VisualIntroPanel::Menu,
            launch_result: Arc::new(Mutex::new(None)),
            image_handle: None,
            font_slots: None,
            text_windows: TextWindowSystem::new(),
            pending_pre_flourish_outcome: None,
            title_tick_frames: None,
            pending_reveal_clicks: Vec::new(),
        };

        let result = std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
            let _ = summarize_intro(&mut intro);
        }));
        let payload = result.expect_err("title summary text fallback must panic");
        let message = payload
            .downcast_ref::<String>()
            .map(String::as_str)
            .or_else(|| payload.downcast_ref::<&str>().copied())
            .expect("title summary panic payload must be a string");
        assert!(message.contains("text fallback is forbidden"), "{message}");
        assert!(message.contains("cleak/u5-spec#71"), "{message}");

        intro.dispatch.dismiss_title();
        intro.message = "Choose a path.".to_string();
        let menu = summarize_intro(&mut intro);
        assert!(menu.contains("Journey Onward"));
        assert!(menu.contains("Create New Character"));
        assert!(menu.contains("Choose a path."));
        let _ = fs::remove_dir_all(&intro.game_dir);
    }

