    fn chargen_records() -> Vec<String> {
        (0..30)
            .map(|index| format!("Questionnaire record {index}"))
            .collect()
    }

    /// Builds an intro state that reads the player's real asset folder.
    ///
    /// Unlike [`visual_intro_state_with_panel`] this never calls
    /// `install_intro_assets`, which copies and rewrites canonical `.BIT`
    /// files into the target directory - harmless for a temp fixture dir,
    /// destructive for `DEFAULT_GAME_DIR`. Tests using this must not write to
    /// or delete `game_dir` either.
    fn read_only_intro_state_for_local_assets(
        game_dir: &Path,
        panel: VisualIntroPanel,
    ) -> VisualIntroState {
        let mut dispatch = UnifiedMenuDispatch::new();
        dispatch.dismiss_title();
        VisualIntroState {
            game_dir: game_dir.to_path_buf(),
            raster_depth: TileGraphicsDepth::Ega16,
            dispatch,
            title_flourish_step: intro_title_flourish_total_steps(),
            title_flourish_complete: true,
            title_signature_progress: 0,
            title_signature_complete: false,
            title_presents_hold_ticks: 0,
            title_sequence_skipped: false,
            pending_auto_return_to_view: false,
            title_tick_frame: 0,
            title_tick_visible_frame: 0,
            surface: new_intro_display_buffer(),
            modal_backing: None,
            menu_idle_ticks: 0,
            menu_idle_bios_ticks: 0,
            menu_cursor_pass: 0,
            menu_cursor_blanked: false,
            message_waiting_for_key: false,
            message: String::new(),
            panel,
            launch_result: Arc::new(Mutex::new(None)),
            image_handle: None,
            font_slots: None,
            text_windows: TextWindowSystem::new(),
            pending_pre_flourish_outcome: None,
            title_tick_frames: None,
            pending_reveal_clicks: Vec::new(),
        }
    }

    fn visual_intro_state_with_panel(
        dir: std::path::PathBuf,
        panel: VisualIntroPanel,
    ) -> VisualIntroState {
        install_intro_assets(&dir);
        let ibm = load_ibm_ch_font(&dir).expect("intro fixtures require IBM.CH");
        let font_slots = IntroFontSlots::new(ibm.clone(), ibm);
        let mut dispatch = UnifiedMenuDispatch::new();
        dispatch.dismiss_title();
        let mut intro = VisualIntroState {
            game_dir: dir,
            raster_depth: TileGraphicsDepth::Ega16,
            dispatch,
            title_flourish_step: intro_title_flourish_total_steps(),
            title_flourish_complete: true,
            title_signature_progress: 0,
            title_signature_complete: false,
            title_presents_hold_ticks: 0,
            title_sequence_skipped: false,
            pending_auto_return_to_view: false,
            title_tick_frame: 0,
            title_tick_visible_frame: 0,
            surface: new_intro_display_buffer(),
            modal_backing: None,
            menu_idle_ticks: 0,
            menu_idle_bios_ticks: 0,
            menu_cursor_pass: 0,
            menu_cursor_blanked: false,
            message_waiting_for_key: false,
            message: String::new(),
            panel,
            launch_result: Arc::new(Mutex::new(None)),
            image_handle: None,
            font_slots: Some(font_slots),
            text_windows: TextWindowSystem::new(),
            pending_pre_flourish_outcome: None,
            title_tick_frames: None,
            pending_reveal_clicks: Vec::new(),
        };
        if matches!(intro.panel, VisualIntroPanel::ReturnToView { .. }) {
            intro.modal_backing = Some(visual_intro_title_art_buffer(&intro.game_dir, None, None));
        }
        intro
    }

    #[test]
    fn visual_intro_character_creation_writes_save_and_returns_to_menu() {
        let dir = debug_game_dir();
        fs::write(
            dir.join(INIT_GAM_FILENAME),
            saved_game_seed_bytes(13, 0, 15, 15),
        )
        .unwrap();
        fs::write(dir.join(INIT_OOL_FILENAME), vec![0x44; OOL_PLANE_LEN]).unwrap();
        let session = ChargenSession::new(chargen_records(), (0u8..=127).collect()).unwrap();
        let mut intro = visual_intro_state_with_panel(
            dir.clone(),
            VisualIntroPanel::CharacterCreation {
                session,
                input_line: String::new(),
            },
        );

        for (key, shift) in [
            (KeyCode::KeyA, true),
            (KeyCode::KeyV, false),
            (KeyCode::KeyA, false),
            (KeyCode::KeyT, false),
            (KeyCode::KeyA, false),
            (KeyCode::KeyR, false),
        ] {
            let ch = key_code_to_char(key, shift, false).expect("name key must map to text");
            step_visual_intro_panel(&mut intro, ch);
        }
        step_visual_intro_panel(&mut intro, '\r');
        step_visual_intro_panel(&mut intro, 'M');
        step_visual_intro_panel(&mut intro, ' ');
        step_visual_intro_panel(&mut intro, ' ');
        for _ in 0..7 {
            step_visual_intro_panel(&mut intro, 'A');
        }
        step_visual_intro_panel(&mut intro, ' ');

        assert!(matches!(intro.panel, VisualIntroPanel::Menu));
        assert!(intro.message.is_empty());
        assert_eq!(
            visual_intro_menu_highlight(&intro),
            IntroSubflow::JourneyOnward,
            "chargen return must make Enter choose Journey Onward instead of restarting chargen"
        );
        assert_eq!(
            render_intro_frame(&mut intro).len(),
            INTRO_FRAMEBUFFER_WIDTH as usize * INTRO_FRAMEBUFFER_HEIGHT as usize * 4,
            "chargen return must redraw the actionable intro menu"
        );
        let saved = fs::read(dir.join(SAVED_GAM_FILENAME)).unwrap();
        assert_eq!(
            &saved[SAVE_ROSTER_OFFSET..SAVE_ROSTER_OFFSET + SAVE_CHARACTER_NAME_LEN - 1],
            b"Avatar\0\0"
        );
        assert_eq!(
            saved[SAVE_ROSTER_OFFSET + SAVE_CHARACTER_GENDER_OFFSET],
            0x0b
        );
        assert_eq!(saved[SAVE_ROSTER_OFFSET + SAVE_CHARACTER_STR_OFFSET], 20);
        assert!(saved[SAVE_ROSTER_OFFSET + SAVE_CHARACTER_DEX_OFFSET] > 0);
        assert!(saved[SAVE_ROSTER_OFFSET + SAVE_CHARACTER_INT_OFFSET] > 0);
        assert_eq!(
            fs::read(dir.join(SAVED_OOL_FILENAME)).unwrap(),
            [vec![0u8; OOL_PLANE_LEN], vec![0x44; OOL_PLANE_LEN]].concat()
        );
        assert!(step_visual_intro(&mut intro, '\r'));
        assert!(
            intro.launch_result.lock().unwrap().is_some(),
            "Enter on the post-chargen menu must load the new save"
        );
        assert!(matches!(intro.panel, VisualIntroPanel::Menu));
        let _ = fs::remove_dir_all(dir);
    }

